import bisect
from typing import List, Tuple


def _parse_field(field: str, max_val: int) -> set:
    values = set()
    for term in field.split(','):
        term = term.strip()
        if not term:
            raise ValueError(f"Empty term in field: {field!r}")

        slash_count = term.count('/')
        if slash_count > 1:
            raise ValueError(f"More than one '/' in term: {term!r}")

        if slash_count == 1:
            base, step_str = term.split('/')
            if not step_str.isdigit():
                raise ValueError(f"Step must be digits only: {term!r}")
            step = int(step_str)
            if step < 1:
                raise ValueError(f"Step must be >= 1: {term!r}")
        else:
            base = term
            step = None

        if base == '*':
            if step is not None:
                values.update(range(0, max_val + 1, step))
            else:
                values.update(range(0, max_val + 1))
        elif '-' in base:
            parts = base.split('-')
            if len(parts) != 2:
                raise ValueError(f"Malformed range in term: {term!r}")
            if not parts[0].isdigit() or not parts[1].isdigit():
                raise ValueError(f"Non-digit in range: {term!r}")
            n = int(parts[0])
            m = int(parts[1])
            if n > m:
                raise ValueError(f"N > M in term: {term!r}")
            if m > max_val:
                raise ValueError(f"Value above MAX in term: {term!r}")
            if step is not None:
                values.update(range(n, m + 1, step))
            else:
                values.update(range(n, m + 1))
        else:
            if not base.isdigit():
                raise ValueError(f"Invalid value in term: {term!r}")
            n = int(base)
            if n > max_val:
                raise ValueError(f"Value above MAX in term: {term!r}")
            if step is not None:
                values.update(range(n, max_val + 1, step))
            else:
                values.add(n)

    return values


def count_fires(spec: str, blackouts: List[Tuple[int, int]], a: int, b: int) -> int:
    P = 10080  # minutes in one week

    if b <= a:
        return 0

    fields = spec.split()
    if len(fields) != 3:
        raise ValueError(f"Expected 3 fields, got {len(fields)}: {spec!r}")

    min_set = _parse_field(fields[0], 59)
    hour_set = _parse_field(fields[1], 23)
    day_set = _parse_field(fields[2], 6)

    # Build sorted list of fire offsets within one week (0 .. P-1)
    F = []
    for d in sorted(day_set):
        for h in sorted(hour_set):
            for m in sorted(min_set):
                F.append(d * 1440 + h * 60 + m)
    F.sort()
    n = len(F)

    # Count fire offsets f in F such that low <= f < high
    def count_week(low: int, high: int) -> int:
        if low >= high:
            return 0
        return bisect.bisect_left(F, high) - bisect.bisect_left(F, low)

    # Count fire offsets in the absolute time range [s, e)
    def count_in_range(s: int, e: int) -> int:
        if s >= e:
            return 0
        s_w, s_o = divmod(s, P)
        e_w, e_o = divmod(e, P)

        if s_w == e_w:
            return count_week(s_o, e_o)
        elif e_w == s_w + 1:
            return count_week(s_o, P) + count_week(0, e_o)
        else:
            return count_week(s_o, P) + (e_w - s_w - 1) * n + count_week(0, e_o)

    # Clip blackouts to [a, b) and discard those that don't intersect
    clipped = []
    for s, e in blackouts:
        if e <= a or s >= b:
            continue
        clipped.append((max(s, a), min(e, b)))

    # Sort and merge overlapping/touching intervals
    clipped.sort()
    merged = []
    for s, e in clipped:
        if not merged:
            merged.append([s, e])
        else:
            if s <= merged[-1][1]:
                merged[-1][1] = max(merged[-1][1], e)
            else:
                merged.append([s, e])

    total = count_in_range(a, b)
    for s, e in merged:
        total -= count_in_range(s, e)

    return total
