from enum import Enum
from typing import Optional


class _State(Enum):
    WAITING = 0
    PAUSED = 1
    RUNNING = 2


class FairQueue:
    def __init__(self, aging: int, cap: int):
        self.aging = aging
        self.cap = cap
        self._jobs: dict[str, dict] = {}
        self._enqueue_counter = 0

    # --- internal helpers ---

    def _total_waited(self, jd: dict, t: int) -> int:
        if jd["state"] is _State.WAITING:
            return jd["waited"] + (t - jd["waiting_since"])
        return jd["waited"]

    def _effective_priority(self, jd: dict, t: int) -> int:
        waited = self._total_waited(jd, t)
        bonus = min(self.cap, waited // self.aging)
        return jd["base"] + bonus

    def _sort_key(self, jd: dict, t: int):
        return (-self._effective_priority(jd, t),
                -self._total_waited(jd, t),
                jd["enqueue_order"])

    # --- public API ---

    def submit(self, job: str, priority: int, t: int) -> None:
        if job in self._jobs:
            raise ValueError(f"Job '{job}' already exists.")
        self._enqueue_counter += 1
        self._jobs[job] = {
            "base": priority,
            "state": _State.WAITING,
            "waited": 0,
            "waiting_since": t,
            "enqueue_order": self._enqueue_counter,
        }

    def start(self, t: int) -> Optional[str]:
        best_name = None
        best_key = None
        for name, jd in self._jobs.items():
            if jd["state"] is _State.WAITING:
                key = self._sort_key(jd, t)
                if best_key is None or key < best_key:
                    best_key = key
                    best_name = name
        if best_name is None:
            return None
        jd = self._jobs[best_name]
        jd["waited"] = self._total_waited(jd, t)
        jd["state"] = _State.RUNNING
        del jd["waiting_since"]
        return best_name

    def finish(self, job: str, t: int) -> None:
        if job not in self._jobs:
            raise KeyError(job)
        jd = self._jobs[job]
        if jd["state"] is not _State.RUNNING:
            raise KeyError(job)
        del self._jobs[job]

    def requeue(self, job: str, t: int) -> None:
        if job not in self._jobs:
            raise KeyError(job)
        jd = self._jobs[job]
        if jd["state"] is not _State.RUNNING:
            raise KeyError(job)
        jd["base"] -= 1
        jd["state"] = _State.WAITING
        jd["waiting_since"] = t
        # jd["waited"] is already finalised (set at start)
        self._enqueue_counter += 1
        jd["enqueue_order"] = self._enqueue_counter

    def pause(self, job: str, t: int) -> bool:
        if job not in self._jobs:
            raise KeyError(job)
        jd = self._jobs[job]
        if jd["state"] is _State.PAUSED:
            return False
        if jd["state"] is _State.WAITING:
            jd["waited"] = self._total_waited(jd, t)
            jd["state"] = _State.PAUSED
            del jd["waiting_since"]
            return True
        raise KeyError(job)

    def resume(self, job: str, t: int) -> bool:
        if job not in self._jobs:
            raise KeyError(job)
        jd = self._jobs[job]
        if jd["state"] is _State.WAITING:
            return False
        if jd["state"] is _State.PAUSED:
            jd["state"] = _State.WAITING
            jd["waiting_since"] = t
            return True
        raise KeyError(job)

    def cancel(self, job: str) -> bool:
        if job in self._jobs:
            del self._jobs[job]
            return True
        return False

    def queue(self, t: int) -> list[tuple[str, int]]:
        items = []
        for name, jd in self._jobs.items():
            if jd["state"] is _State.WAITING:
                items.append((self._sort_key(jd, t), name, self._effective_priority(jd, t)))
        items.sort()
        return [(name, ep) for _, name, ep in items]
