import heapq
from collections import defaultdict


def ferry_plan(routes: list[tuple[str, str, int, int, int]], src: str, dst: str, t0: int):
    if src == dst:
        return (t0, 0)

    # Build adjacency list, ignoring self-loops
    adj = defaultdict(list)
    for a, b, first, every, duration in routes:
        if a == b:
            continue
        adj[a].append((b, first, every, duration))

    # Maximum ferry count: at most (num_ports - 1) ferries in a simple path
    all_ports = set()
    for a, b, _, _, _ in routes:
        all_ports.add(a)
        all_ports.add(b)
    all_ports.add(src)
    all_ports.add(dst)

    max_fc = max(len(all_ports) + 1, 60)

    # dist[port][fc] = earliest arrival time at `port` using exactly `fc` ferries
    dist = {}
    for p in all_ports:
        dist[p] = [float('inf')] * (max_fc + 1)

    dist[src][0] = t0

    # Min-heap: (arrival_time, ferry_count, port)
    heap = [(t0, 0, src)]
    visited = set()  # (time, fc, port) already processed

    while heap:
        time, fc, port = heapq.heappop(heap)
        if time > dist[port][fc]:
            continue
        if (time, fc, port) in visited:
            continue
        visited.add((time, fc, port))

        # Relax all outgoing ferries from this port
        for next_port, first, every, duration in adj.get(port, []):
            next_fc = fc + 1
            if next_fc > max_fc:
                continue
            # Next departure time: first + k * every where k = max(0, ceil((time - first) / every))
            if time <= first:
                depart = first
            else:
                k = (time - first + every - 1) // every
                depart = first + k * every
            arrive = depart + duration
            if arrive < dist[next_port][next_fc]:
                dist[next_port][next_fc] = arrive
                heapq.heappush(heap, (arrive, next_fc, next_port))

    # Find best (earliest time, then fewest ferries) at dst
    best_time = float('inf')
    best_fc = float('inf')
    for fc in range(max_fc + 1):
        t = dist[dst][fc]
        if t < best_time:
            best_time = t
            best_fc = fc
        elif t == best_time and fc < best_fc:
            best_fc = fc

    if best_time == float('inf'):
        return None
    return (best_time, best_fc)
